import WebSocket from 'ws';
// Tiny PNG generated by scripts/probe-vision.py using Python's standard library.
import { deflateSync } from 'node:zlib';

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) { crc ^= byte; for (let i = 0; i < 8; i++) crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1)); }
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const name = Buffer.from(type), out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length); name.copy(out, 4); data.copy(out, 8); out.writeUInt32BE(crc32(Buffer.concat([name, data])), 8 + data.length); return out;
}
const header = Buffer.alloc(13); header.writeUInt32BE(64, 0); header.writeUInt32BE(64, 4); header[8] = 8; header[9] = 2;
const scanline = Buffer.alloc(1 + 64 * 3); for (let i = 0; i < 64; i++) scanline[1 + i * 3] = 255;
const png = Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]), chunk('IHDR', header), chunk('IDAT', deflateSync(Buffer.concat(Array(64).fill(scanline)))), chunk('IEND', Buffer.alloc(0))]);
const socket = new WebSocket(process.env.ASSISTAI_TEST_VOICE_URL ?? 'ws://127.0.0.1:18089/voice');
let answer = '', audio = 0;
const timer = setTimeout(() => { console.error('Vision probe timed out'); process.exitCode = 1; socket.close(); }, 60000);
socket.on('open', () => socket.send(JSON.stringify({ type: 'image', text: 'Quelle est la couleur dominante ? Réponds en un mot.', image: `data:image/png;base64,${png.toString('base64')}` })));
socket.on('message', (data, binary) => {
  if (binary) { audio += data.length; return; }
  const event = JSON.parse(data.toString());
  if (event.type === 'assistant.text') answer = event.text;
  if (event.type === 'error') { console.error(event.message); process.exitCode = 1; clearTimeout(timer); socket.close(); }
  if (event.type === 'speech.end') { console.log(JSON.stringify({ answer, audio_bytes: audio })); if (!/rouge/i.test(answer) || !audio) process.exitCode = 1; clearTimeout(timer); socket.close(); }
});
socket.on('error', error => { console.error(error.message); process.exitCode = 1; clearTimeout(timer); });
